import React from 'react';
import loadable from '@loadable/component';
import { useLocation } from 'react-router-dom';
import { useCategory } from '@salesforce/commerce-sdk-react';
import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
import { HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
import Seo from '@salesforce/retail-react-app/app/components/seo';
import { Box, Skeleton, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
import { categoryIdFromPathSegments, removeSiteLocaleFromPath } from '../../utils/url';

const fallback = <Skeleton height="75vh" width="100%" />;

// Loadable rather than static imports so this dispatcher stays a small chunk and the PLP and
// Experience pages keep the code-split boundaries routes.tsx already gives them.
const ProductList = loadable(() => import('../product-list'), { fallback });
const Experience = loadable(() => import('../experience'), { fallback });

const HTTP_NOT_FOUND = 404;
const HTTP_INTERNAL_SERVER_ERROR = 500;

/** The path segments of the current page with the site/locale prefix removed. */
export const pathSegments = (pathname: string): string[] =>
  removeSiteLocaleFromPath(pathname).split('/').filter(Boolean);

type CategoryPathProps = {
  /** Path segments to resolve; defaults to the current location. Exposed for tests. */
  segments?: readonly string[];
};

/**

=== useContentful.ts: the filter/locale signature (reusable for category-ID keying) ===
 * Fetches all Contentful entries of a given content type and resolves their linked assets/entries.
 *
 * @param contentType - Contentful content type ID (e.g. 'iconAndText').
 * @param preview - When true, uses the Preview API (draft content). Defaults to false.
 * @param locale - Optional locale string (e.g. 'en-AU'). Omit to use Contentful's default.
 * @param filter - Optional additional Contentful query filter appended to the request
 *   (e.g. `'fields.placement=benefits'`). Follows Contentful's Search Parameters syntax.
 * @returns `{ data, isLoading, error }` where `data` is typed as `T[] | null`.
 */
export const useContentfulEntries = <T>(contentType: string, preview = false, locale?: string, filter?: string) => {
  const [data, setData] = useState<T[] | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    // Reset rather than leaving the previous request's data/error in place — without this,
    // a locale change on an already-mounted consumer (e.g. UiCopyProvider) would keep
    // rendering the old locale's content until the new fetch resolves.
    setIsLoading(true);
    setError(null);
    setData(null);

    const fetchEntries = async () => {
      try {
        const config = getValidatedContentfulConfig();
        const query = filter ? `content_type=${contentType}&${filter}` : `content_type=${contentType}`;
        const url = buildContentfulUrl(query, config, preview, locale);
        const response = await fetch(url, { signal: controller.signal });

        if (!response.ok) {
          throw new Error(`Contentful API error: ${response.status}`);
        }

        const result: ContentfulEntriesResponse = await response.json();
        const resolvedItems = result.items.map((item) => resolveLinkedAssets(item, result.includes));
        setData(resolvedItems as T[]);
      } catch (err) {
        if (err instanceof DOMException && err.name === 'AbortError') return;
